export function EventsDemo() {
  const snack = __snackBar;
  const [count, setCount] = useState(0);
  const increment = () => {
    setCount(count + 1);
  };
  const decrement = () => {
    setCount(count - 1);
  };
  const announce = () => {
    snack.open('Button clicked!');
  };
  return (
    <>
      <RgText variant="display">{count}</RgText>
      <RgButton onPress={() => increment()}>Increment</RgButton>
      <RgButton disabled={(count === 0)} onPress={() => decrement()}>Decrement</RgButton>
      <RgButton onPress={() => announce()}>Show a toast</RgButton>
    </>
  );
}

export function BindingsDemo() {
  const [count, setCount] = useState(0);
  const increment = () => {
    setCount(count + 1);
  };
  const reset = () => {
    setCount(0);
  };
  return (
    <>
      <RgText variant="display">{count}</RgText>
      <RgButton onPress={() => increment()}>Increment</RgButton>
      <RgButton disabled={(count === 0)} onPress={() => reset()}>Reset</RgButton>
      {(count >= 5) && (
        <RgText variant="bodyLarge">Past five. Keep going.</RgText>
      )}
      {(count === 0) && (
        <RgText variant="bodyLarge">Reset is disabled while the count is zero. That is property binding at work.</RgText>
      )}
    </>
  );
}

export function ListsDemo() {
  const [items, setItems] = useState(['Morning yoga', 'Puja', 'Deep work']);
  const pool = ['Evening walk', 'Reading', 'Trikala Sandhya', 'Completion process'];
  const [next, setNext] = useState(0);
  const add = () => {
    const item = pool[next % pool.length];
    setNext(next + 1);
    setItems([...items, item]);
  };
  const removeLast = () => {
    setItems(items.slice(0, items.length - 1));
  };
  const clear = () => {
    setItems([]);
  };
  return (
    <>
      <RgList>
        {items.map((item, i) => (
          <RgRow key={item?.id ?? i} title={item} detail={('Item ' + (i + 1))} />
        ))}
      </RgList>
      {(items.length === 0) && (
        <RgText variant="bodyLarge">The list is empty. ngFor over an empty array renders nothing.</RgText>
      )}
      <RgText variant="bodyLarge">{items.length} items in the array, {items.length} rows on screen.</RgText>
      <RgButton onPress={() => add()}>Add an item</RgButton>
      <RgButton disabled={(items.length === 0)} onPress={() => removeLast()}>Remove the last</RgButton>
      <RgButton disabled={(items.length === 0)} onPress={() => clear()}>Clear the list</RgButton>
    </>
  );
}

export function NgifDemo() {
  const [signedIn, setSignedIn] = useState(false);
  const toggle = () => {
    setSignedIn(!signedIn);
  };
  return (
    <>
      {signedIn && (
        <RgSection>
          <RgText variant="title">Welcome back</RgText>
          <RgText variant="bodyLarge">You are signed in, so this panel renders. Its opposite below does not.</RgText>
        </RgSection>
      )}
      {!signedIn && (
        <RgSection>
          <RgText variant="title">Please sign in</RgText>
          <RgText variant="bodyLarge">You are signed out, so this panel renders instead. Together the two panels are the else pattern.</RgText>
        </RgSection>
      )}
      <RgButton onPress={() => toggle()}>{(signedIn ? 'Sign out' : 'Sign in')}</RgButton>
      <RgText variant="bodyLarge">Status: {(signedIn ? 'signed in' : 'signed out')}, chosen by a ternary.</RgText>
    </>
  );
}

export function ClassStyleDemo() {
  const [look, setLook] = useState('calm');
  const [highlighted, setHighlighted] = useState(false);
  const [ownLine, setOwnLine] = useState('My own line');
  const show = (look: string) => {
    setLook(look);
  };
  const toggleHighlight = () => {
    setHighlighted(!highlighted);
  };
  return (
    <>
      {(look === 'calm') && (
        <RgText variant="bodyLarge" style={styles.classStyleDemoLookCalm}>A calm line, styled by the look-calm class.</RgText>
      )}
      {(look === 'alert') && (
        <RgText variant="bodyLarge" style={styles.classStyleDemoLookAlert}>An alert line, styled by the look-alert class.</RgText>
      )}
      {(look === 'big') && (
        <RgText variant="bodyLarge" style={styles.classStyleDemoLookBig}>A big line, styled by the look-big class.</RgText>
      )}
      <RgButton onPress={() => show('calm')}>Calm</RgButton>
      <RgButton onPress={() => show('alert')}>Alert</RgButton>
      <RgButton onPress={() => show('big')}>Big</RgButton>
      <RgText variant="bodyLarge" style={highlighted ? styles.classStyleDemoLookHighlight : undefined}>This line carries a class binding. The highlight class turns on and off with the button below.</RgText>
      <RgButton onPress={() => toggleHighlight()}>Toggle highlight</RgButton>
      <RgInput label="Try it: your own line, in all three looks" value={ownLine} onChangeText={($event) => setOwnLine($event)} />
      <RgText variant="bodyLarge" style={styles.classStyleDemoLookCalm}>{ownLine}</RgText>
      <RgText variant="bodyLarge" style={styles.classStyleDemoLookAlert}>{ownLine}</RgText>
      <RgText variant="bodyLarge" style={styles.classStyleDemoLookBig}>{ownLine}</RgText>
    </>
  );
}

