export function InputsDemo() {
  const teachers = [
    { name: 'Acharya Rajan', role: 'Yoga' },
    { name: 'Pankaj Shukla', role: 'AI and agents' },
    { name: 'Monika Sogam', role: 'Guided meditation voice' },
  ];
  const [index, setIndex] = useState(0);
  const [teacherName, setTeacherName] = useState('Acharya Rajan');
  const [teacherRole, setTeacherRole] = useState('Yoga');
  const cycle = () => {
    setIndex((index + 1) % teachers.length);
    setTeacherName(teachers[index].name);
    setTeacherRole(teachers[index].role);
  };
  return (
    <>
      <GreetingCard name={teacherName} role={teacherRole} />
      <RgButton onPress={() => cycle()}>Next teacher</RgButton>
    </>
  );
}

