export function LifecycleDemo() {
  const log = __container.get<LifecycleLogService>(LifecycleLogService);
  useSyncExternalStore((cb) => log.__subscribe(cb), () => log.__getVersion());
  const [show, setShow] = useState(false);
  const toggle = () => {
    setShow(!show);
  };
  return (
    <>
      <RgButton onPress={() => toggle()}>{(show ? 'Remove the stamp' : 'Show the stamp')}</RgButton>
      {show && (
        <Stamp />
      )}
      <RgText variant="label">The lifecycle log</RgText>
      {(log.entries.length === 0) && (
        <RgText variant="bodyLarge">No calls yet. Show the stamp and watch this log.</RgText>
      )}
      {log.entries.map((entry, index) => (
        <RgText key={entry?.id ?? index} variant="bodyLarge">{entry}</RgText>
      ))}
    </>
  );
}

export function Stamp() {
  const log = __container.get<LifecycleLogService>(LifecycleLogService);
  useSyncExternalStore((cb) => log.__subscribe(cb), () => log.__getVersion());
  const ngOnInit = () => {
    log.entries = [...log.entries, 'Stamp created: ngOnInit ran'];
  };
  const ngOnDestroy = () => {
    log.entries = [...log.entries, 'Stamp removed: ngOnDestroy ran'];
  };
  useEffect(() => {
    ngOnInit();
    return () => {
      ngOnDestroy();
    };
  }, []);
  return (
    <RgText variant="bodyLarge">The stamp is on screen right now.</RgText>
  );
}

