export function SetValueDemo() {
  const [changes, setChanges] = useState(0);
  const profileFormRef = useRef(new FormGroup({
    name: new FormControl(''),
    city: new FormControl(''),
  }));
  const [, setFormVersion] = useState(0);
  useEffect(() => {
    const subs = [
      ...Object.values(profileFormRef.current.controls).map((control) => control.valueChanges.subscribe(() => setFormVersion((v) => v + 1))),
    ];
    return () => { subs.forEach((sub) => sub.unsubscribe()); };
  }, []);
  const ngOnInit = () => {
    profileFormRef.current.get('name').valueChanges.subscribe((v) => {
  setChanges(changes + 1);
});
  };
  const fillSample = () => {
    profileFormRef.current.get('name').setValue('Maya');
    profileFormRef.current.get('city').setValue('Pokhara');
  };
  const clearAll = () => {
    profileFormRef.current.get('name').setValue('');
    profileFormRef.current.get('city').setValue('');
  };
  useEffect(() => {
    ngOnInit();
  }, []);
  return (
    <View>
      <RgInput label="Name" placeholder="Your name" value={profileFormRef.current.get('name').value} onChangeText={($event) => profileFormRef.current.get('name').setValue($event)} onBlur={() => { profileFormRef.current.get('name').markAsTouched(); setFormVersion((v) => v + 1); }} />
      <RgInput label="City" placeholder="Your city" value={profileFormRef.current.get('city').value} onChangeText={($event) => profileFormRef.current.get('city').setValue($event)} onBlur={() => { profileFormRef.current.get('city').markAsTouched(); setFormVersion((v) => v + 1); }} />
      <RgText variant="bodyLarge">Name dirty: {(profileFormRef.current.get('name').dirty ? 'yes' : 'no')}</RgText>
      <RgText variant="bodyLarge">Name changes reported by valueChanges: {changes}</RgText>
      <RgButton onPress={() => fillSample()}>Fill a sample</RgButton>
      <RgButton onPress={() => clearAll()}>Clear</RgButton>
    </View>
  );
}

