export function TablesDepthDemo() {
  const [people, setPeople] = useState([
    { name: 'Mina', age: 31, city: 'Kathmandu' },
    { name: 'Arun', age: 25, city: 'Pokhara' },
    { name: 'Sita', age: 40, city: 'Bhaktapur' },
    { name: 'Bikash', age: 25, city: 'Kathmandu' },
    { name: 'Anita', age: 36, city: 'Patan' },
    { name: 'Kiran', age: 29, city: 'Pokhara' },
    { name: 'Rita', age: 33, city: 'Bhaktapur' },
  ]);
  const extras = [
    { name: 'Hari', age: 27, city: 'Dharan' },
    { name: 'Gita', age: 38, city: 'Butwal' },
    { name: 'Nabin', age: 24, city: 'Hetauda' },
  ];
  const [added, setAdded] = useState(0);
  const addPerson = () => {
    setPeople([...people, extras[added]]);
    setAdded(added + 1);
  };
  const removeLast = () => {
    setPeople(people.slice(0, people.length - 1));
  };
  return (
    <>
      <RgText variant="label">People, three to a page. Name and Age sort; City does not.</RgText>
      <RgTable pageSize="3" data={people}>
        <RgColumn name="name" header="Name" />
        <RgColumn name="age" header="Age" />
        <RgColumn name="city" header="City" />
      </RgTable>
      <RgButton disabled={(added >= 3)} onPress={() => addPerson()}>Add a person</RgButton>
      <RgButton disabled={(people.length <= 3)} onPress={() => removeLast()}>Remove the last</RgButton>
      <RgText variant="bodyLarge">Rows in the array: {people.length}. Remove rows down to three and the pager goes away: the rows fit on one page.</RgText>
      <RgText variant="label">The array itself, in its own order</RgText>
      <RgList>
        {people.map((p, index) => (
          <RgRow key={p?.id ?? index} title={p.name} />
        ))}
      </RgList>
    </>
  );
}

