export function RefreshDemo() {
  const [refreshing, setRefreshing] = useState(false);
  const [refreshCount, setRefreshCount] = useState(0);
  const [notes, setNotes] = useState([
    { id: 1, title: 'Morning practice', detail: 'Sunrise session, 25 minutes' },
    { id: 2, title: 'Reading', detail: 'Part 23 of the series' },
    { id: 3, title: 'Walk', detail: 'The river road, there and back' },
  ]);
  const reload = () => {
    setRefreshing(true);
    setRefreshCount(refreshCount + 1);
    setNotes([{ id: 100 + refreshCount, title: 'Fresh note ' + refreshCount, detail: 'Pulled in by your refresh' }].concat(notes));
    setRefreshing(false);
  };
  return (
    <>
      <RgText variant="bodyLarge">Pull the list down to refresh it. Each refresh puts a fresh note on top.</RgText>
      <RgList refreshing={refreshing} onRefresh={() => reload()}>
        {notes.map((n, index) => (
          <RgRow key={n?.id ?? index} title={n.title} detail={n.detail} />
        ))}
      </RgList>
      {(refreshCount > 0) && (
        <RgText variant="bodyLarge">Refreshed {refreshCount} times.</RgText>
      )}
      {(refreshCount === 0) && (
        <RgText variant="bodyLarge">Not refreshed yet. The count line will stand here after the first pull.</RgText>
      )}
    </>
  );
}

export function InfiniteScrollDemo() {
  const firstPage = [
    { id: 1, title: 'Article 1: Begin with the breath' },
    { id: 2, title: 'Article 2: The spine, held easy' },
    { id: 3, title: 'Article 3: Sitting without force' },
    { id: 4, title: 'Article 4: Attention returns' },
  ];
  const morePages = [
    [
      { id: 5, title: 'Article 5: The witness stance' },
      { id: 6, title: 'Article 6: Sound and silence' },
      { id: 7, title: 'Article 7: The pause between' },
      { id: 8, title: 'Article 8: Ending well' },
    ],
    [
      { id: 9, title: 'Article 9: Carrying it into the day' },
      { id: 10, title: 'Article 10: Review and rest' },
    ],
  ];
  const [items, setItems] = useState([
    { id: 1, title: 'Article 1: Begin with the breath' },
    { id: 2, title: 'Article 2: The spine, held easy' },
    { id: 3, title: 'Article 3: Sitting without force' },
    { id: 4, title: 'Article 4: Attention returns' },
  ]);
  const [page, setPage] = useState(0);
  const [done, setDone] = useState(false);
  const loadMore = () => {
    setItems(items.concat(morePages[page] || []));
    setPage(page + 1);
    setDone(page >= morePages.length);
  };
  const reset = () => {
    setItems([...firstPage]);
    setPage(0);
    setDone(false);
  };
  return (
    <>
      <RgText variant="bodyLarge">Scroll to the end of the list. The next page appends on its own.</RgText>
      <RgList onEndReached={() => loadMore()}>
        {items.map((a, index) => (
          <RgRow key={a?.id ?? index} title={a.title} />
        ))}
      </RgList>
      {done && (
        <RgText variant="bodyLarge">That is the whole list: {items.length} articles.</RgText>
      )}
      {done && (
        <RgButton onPress={() => reset()}>Start the list again</RgButton>
      )}
    </>
  );
}

