export function RowActionsDemo() {
  const [lastAction, setLastAction] = useState('');
  const [mails, setMails] = useState([
    { id: 1, from: 'Sarju', subject: 'Photos from the weekend' },
    { id: 2, from: 'Medium', subject: 'Your weekly reading list' },
    { id: 3, from: 'Field Notes', subject: 'Transformer testing, day one' },
    { id: 4, from: 'Google', subject: 'Security alert' },
  ]);
  const star = (subject: string) => {
    setLastAction('Starred: ' + subject);
  };
  const remove = (subject: string) => {
    setMails(mails.filter((m) => m.subject !== subject));
    setLastAction('Deleted: ' + subject);
  };
  return (
    <>
      <RgText variant="bodyLarge">Swipe a row to the side and tap an action. In the preview, a small reveal handle stands in for the swipe.</RgText>
      <RgList>
        {mails.map((m, index) => (
          <RgRow key={m?.id ?? index} title={m.from} subtitle={m.subject}>
            <RgRowAction icon="star" onPress={() => star(m.subject)}>Star</RgRowAction>
            <RgRowAction icon="delete" color="error" onPress={() => remove(m.subject)}>Delete</RgRowAction>
          </RgRow>
        ))}
      </RgList>
      {lastAction && (
        <RgText variant="bodyLarge">{lastAction}</RgText>
      )}
      {(mails.length === 0) && (
        <RgText variant="bodyLarge">The inbox is empty. Every row was deleted by its own swipe action.</RgText>
      )}
    </>
  );
}

