export default function App() {
  const [__route, __setRoute] = useState(__navigator.current);
  useEffect(() => __navigator.subscribe(() => __setRoute(__navigator.current)), []);
  const [__snack, __setSnack] = useState(__snackBar.current);
  useEffect(() => __snackBar.subscribe(() => __setSnack(__snackBar.current)), []);
  return (
    <>
      <RgScreen>
        <RgOutlet>
          {__route.routePath === "splash" && (
            <Splash key={__route.path} />
          )}
          {__route.routePath === "home" && (
            <Home key={__route.path} />
          )}
          {__route.routePath === "lesson/:id" && (
            <Lesson key={__route.path} __rgRoute={new ActivatedRoute(__route.params, __navigator)} />
          )}
          {__route.routePath === "about" && (
            <About key={__route.path} />
          )}
          {__route.routePath === "**" && (
            <NotFound key={__route.path} />
          )}
        </RgOutlet>
      </RgScreen>
      {__snack && (<RgSnackbar message={__snack.message} actionLabel={__snack.actionLabel} onAction={() => __snackBar.pressAction()} />)}
    </>
  );
}

